kits.snippet:
// 飞到某个经纬度范围并等动画结束（自动解除 lookAt 锁定）
const r = await kit.camera.flyToRegion(
  { west: 116.2, south: 39.7, east: 116.7, north: 40.1 },
  { duration: 2 },
);
return r;

// 免 key 影像底图 + 3D 地形（ArcGIS 公开服务），再批量采样高程（弧度由库内转换）
await kit.imagery.addArcGisImagery();
await kit.imagery.enableTerrain3D();
const h = await kit.imagery.sampleHeights([{ lon: 86.925, lat: 27.988 }]);   // 珠峰
await kit.camera.flyToRegion({ west: 116.2, south: 39.7, east: 116.7, north: 40.1 });
return { everest: h.heights[0] };

// 加载武汉市边界（贴地）并飞过去；想连下级区县一起加载传 { full: true }
const r = await kit.geojson.loadAdmin(420100, { flyTo: true });
return { name: r.properties?.name, features: r.featureCount, url: r.url };

// 贴地画一个多边形（左键加点 / 右键撤销 / 双击结束），结束回调给出经纬度序列
const out = await new Promise((resolve) => {
  kit.drawer.start({
    type: 'POLYGON',
    pick: 'terrain',
    style: { color: '#00CED1', outlineColor: '#FFD700' },
    dynamicStyle: { color: '#00CED1', alpha: 0.15 },
    onEnd: resolve,
  });
});
return { count: out.count, points: out.points };

// 两点贴地距离（surface 沿地表，plane 走椭球面测地线）
const d = kit.measure.distance(
  { lon: 116.39, lat: 39.90 },
  { lon: 116.42, lat: 39.95 },
);

// 多边形贴地面积（至少 3 点，自动闭合）
const a = kit.measure.area([
  { lon: 116.39, lat: 39.90 },
  { lon: 116.42, lat: 39.90 },
  { lon: 116.42, lat: 39.93 },
  { lon: 116.39, lat: 39.93 },
]);
return { distance: d, area: a };

const p = kit.overlay.popup({
  lon: 116.39, lat: 39.90,
  content: '<b>标题</b><br/>说明文字',
});

// 跟随鼠标的坐标提示
const tip = kit.overlay.tooltip();

return { popupId: p.id, tooltipId: tip.id };

// 加载 3D Tiles（换成你的 tileset.json）+ ENU 正确抬升 80m + 按模型高度染色
const { tileset } = await kit.tiles.load('https://your-host/tileset.json', { zoom: true });
kit.tiles.lift(tileset, 80);
kit.tiles.setShader(tileset, {
  fragmentShaderText: `void fragmentMain(FragmentInput fsInput, inout czm_modelMaterial material) {
    float h = fsInput.attributes.positionMC.y;
    material.diffuse = mix(vec3(0.2, 0.6, 1.0), vec3(1.0, 0.4, 0.0), clamp(h / 120.0, 0.0, 1.0));
  }`,
});
return 'ok —— 清除用 kit.tiles.clearShader(tileset)';

// 一万条随机点（Collection 单次 batch，远处自动缩小）——Entity 逐个加会崩帧率
const items = Array.from({ length: 10000 }, () => ({
  lon: 73 + Math.random() * 62, lat: 18 + Math.random() * 30,
  color: '#38f', pixelSize: 6,
}));
const r = kit.points.addMany(items, { scaleByDistance: [2.0e6, 1.0, 8.0e6, 0.1] });
return { ...r, hint: 'kit.points.clear() 一键清空' };

// 一段三点轨迹动画（北京→天津方向），循环播放，5 倍速
const h = kit.motion.animatePath(
  [{ lon: 116.39, lat: 39.9, height: 5000 }, { lon: 117.2, lat: 39.2, height: 5000 }, { lon: 117.8, lat: 38.9, height: 5000 }],
  { multiplier: 5 },
);
return { id: h.id, hint: 'kit.motion.stopAll() 停止并恢复时钟' };

// 雨 / 雪 / 雾三选一，句柄可随时摘除；换效果不用手动 remove
await kit.camera.flyToRegion({ west: 116.2, south: 39.7, east: 116.7, north: 40.1 }, { duration: 1 });
const rain = kit.effects.rain({ alpha: 0.4 });
// const snow = kit.effects.snow(); const fog = kit.effects.fog({ density: 0.0002 });
return { active: rain.name, hint: 'rain.remove() 摘除; kit.effects.stopAll() 全清' };

// 三类地形分析：开挖（还原用 restore）/ 淹没（自动封顶）/ 通视（要真实地形）
const dig = kit.analysis.excavate([{ lon: 116.39, lat: 39.90 }, { lon: 116.42, lat: 39.90 }, { lon: 116.42, lat: 39.93 }, { lon: 116.39, lat: 39.93 }]);
const water = kit.analysis.flood([{ lon: 116.39, lat: 39.90 }, { lon: 116.42, lat: 39.90 }, { lon: 116.42, lat: 39.93 }, { lon: 116.39, lat: 39.93 }], { startHeight: 0, endHeight: 50, seconds: 30 });
const see = await kit.analysis.intervisibility({ lon: 116.39, lat: 39.90 }, { lon: 116.42, lat: 39.93 });
return { planes: dig.planes, waterId: water.id, blocked: see.blocked, minClearance: see.minClearance };
